@namespace sv_65a05fb104e9442c995dcd32ca11dd74.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var isCompleted = CompletedSteps.Contains(stepIndex);
        var isCurrent = stepIndex == CurrentStep;
        var cssClass = isCurrent ? "step current" : isCompleted ? "step completed" : "step future";

        <button class="@cssClass"
                disabled="@(!isCompleted && !isCurrent)"
                @onclick="() => OnStepClicked.InvokeAsync(stepIndex)"
                aria-current="@(isCurrent ? "step" : null)">
            <span class="step-number">
                @if (isCompleted)
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    @(stepIndex + 1)
                }
            </span>
            <span class="step-label">@StepNames[stepIndex]</span>
        </button>

        @if (stepIndex < StepNames.Count - 1)
        {
            <span class="step-connector @(isCompleted ? "completed" : "")"></span>
        }
    }
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
