@page "/apply"
@using sv_65a05fb104e9442c995dcd32ca11dd74.Components.Pages.Apply
@using sv_65a05fb104e9442c995dcd32ca11dd74.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@_currentStep"
                   CompletedSteps="@_completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@_fullName"
                              Email="@_email"
                              Phone="@_phone"
                              Address="@_address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalInfoNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="@_workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep References="@_references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep PersonalFullName="@_fullName"
                        PersonalEmail="@_email"
                        PersonalPhone="@_phone"
                        PersonalAddress="@_address"
                        WorkEntries="@_workEntries"
                        References="@_references"
                        CoverLetter="@_coverLetter"
                        OnEditStep="GoToStep"
                        OnBack="GoBack"
                        SubmitApplication="HandleSubmit" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private readonly HashSet<int> _completedSteps = new();

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 state
    private List<WorkEntryForm.WorkEntryModel> _workEntries = new() { new() };

    // Step 3 state
    private List<ReferenceForm.ReferenceModel> _references = new() { new(), new() };

    // Step 4 state
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        if (_completedSteps.Contains(step) || step == _currentStep)
        {
            _currentStep = step;
        }
    }

    private void GoBack()
    {
        if (_currentStep > 0)
        {
            _currentStep--;
        }
    }

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        _fullName = result.FullName;
        _email = result.Email;
        _phone = result.Phone;
        _address = result.Address;
        _completedSteps.Add(0);
        _currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        _workEntries = entries;
        _completedSteps.Add(1);
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> references)
    {
        _references = references;
        _completedSteps.Add(2);
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _completedSteps.Add(3);
        _currentStep = 4;
    }

    private async Task<int> HandleSubmit()
    {
        var workHistory = new WorkHistory(_workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());

        var refs = _references.Select(r =>
            new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

        var personal = new PersonalInfo(_fullName, _email, _phone, _address);
        var application = new JobApplication(personal, workHistory, refs, _coverLetter);

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.apply-container {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-container h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step-indicator .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    min-width: 80px;
    transition: opacity 0.2s;
}

.step-indicator .step:disabled {
    cursor: not-allowed;
}

.step-indicator .step.future {
    opacity: 0.4;
}

.step-indicator .step.current .step-number {
    background: #4361ee;
    color: white;
    font-weight: bold;
}

.step-indicator .step.completed .step-number {
    background: #2ec4b6;
    color: white;
}

.step-number {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #e0e0e0;
    color: #666;
    font-size: 0.85rem;
    margin-bottom: 0.25rem;
}

.checkmark {
    font-size: 1rem;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #333;
}

.step-connector {
    width: 30px;
    height: 2px;
    background: #e0e0e0;
    align-self: center;
    margin-bottom: 1.2rem;
}

.step-connector.completed {
    background: #2ec4b6;
}

/* Form Steps */
.form-step {
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
    margin-top: 1rem;
}

.form-step h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

.step-description {
    color: #666;
    margin-bottom: 1rem;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.3rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.15);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    font-weight: normal !important;
    margin-top: 0.4rem;
    font-size: 0.85rem;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

.btn {
    padding: 0.6rem 1.5rem;
    border: none;
    border-radius: 4px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #4361ee;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #3451d1;
}

.btn-outline {
    background: transparent;
    border: 1px solid #4361ee;
    color: #4361ee;
}

.btn-outline:hover {
    background: #f0f3ff;
}

.btn-secondary {
    background: #f0f0f0;
    color: #333;
    margin-top: 1rem;
}

.btn-secondary:hover {
    background: #e0e0e0;
}

.btn-danger {
    background: #e63946;
    color: white;
}

.btn-sm {
    padding: 0.3rem 0.8rem;
    font-size: 0.8rem;
}

.btn-link {
    background: none;
    border: none;
    color: #4361ee;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1.05rem;
}

/* Validation */
.validation-summary {
    background: #fff3f3;
    border: 1px solid #e63946;
    color: #e63946;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-top: 1rem;
    font-size: 0.9rem;
}

.field-error {
    color: #e63946;
    font-size: 0.8rem;
    margin-top: 0.2rem;
    display: block;
}

/* Work Entry & Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.work-entry-header,
.reference-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h4,
.reference-header h4 {
    margin: 0;
    color: #333;
}

/* Cover Letter */
.cover-letter-textarea {
    resize: vertical;
    min-height: 200px;
}

.char-count {
    display: block;
    text-align: right;
    color: #666;
    font-size: 0.8rem;
    margin-top: 0.3rem;
}

/* Review Step */
.review-section {
    border-bottom: 1px solid #eee;
    padding-bottom: 1rem;
    margin-bottom: 1rem;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.review-section-header h3 {
    margin: 0 0 0.5rem 0;
    color: #1a1a2e;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.3rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #666;
}

.review-section dd {
    margin: 0;
}

.review-work-entry {
    margin-bottom: 0.75rem;
    padding-left: 0.5rem;
    border-left: 3px solid #4361ee;
}

.review-dates {
    font-size: 0.85rem;
    color: #666;
}

.review-description {
    margin: 0.3rem 0 0 0;
    font-size: 0.9rem;
    color: #555;
}

.review-reference {
    margin-bottom: 0.5rem;
}

.review-cover-letter {
    white-space: pre-wrap;
    background: #f8f8f8;
    padding: 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 2rem;
}

.submission-confirmation h3 {
    color: #2ec4b6;
    font-size: 1.5rem;
}

/* Responsive */
@media (max-width: 600px) {
    .form-row {
        grid-template-columns: 1fr;
    }

    .step-indicator {
        gap: 0.1rem;
    }

    .step-label {
        font-size: 0.65rem;
    }
}

